# Generated by test-lab — blind adversarial evaluation
"""Regression tests for Memory-derived code context recovery."""

from live_evidence.code_context import current_source_query_from_memory
from live_evidence.models import EvidenceSource, Freshness, RetrievalLane


def _memory_source(label: str, excerpt: str) -> EvidenceSource:
    return EvidenceSource(
        lane=RetrievalLane.MEMORY,
        label=label,
        excerpt=excerpt,
        score=0.9,
        freshness=Freshness.UNKNOWN,
        path="project_memory_versions/example",
    )


def test_memory_leetcode_source_expands_current_source_query() -> None:
    query = "parenthesis always has to come before closing, right?"
    sources = [
        _memory_source(
            "LeetCode: Minimum Remove to Make Valid Parentheses",
            "Given a string with opening and closing parentheses, remove the "
            "minimum number of parentheses so the result is valid.",
        )
    ]

    expanded = current_source_query_from_memory(query, sources)

    assert "remove the minimum number of parentheses" in expanded
    assert "source code implementation" in expanded
    assert "remove_invalid_parentheses" in expanded


def test_non_code_memory_does_not_expand_current_source_query() -> None:
    expanded = current_source_query_from_memory(
        "what are the hard rules?",
        [_memory_source("Project Memory", "Read the SKILL.md in full.")],
    )

    assert expanded == ""
